namespace ghidra.app.plugin.processors.generic;




using ghidra.program.model.address;
using ghidra.program.model.address;
using ghidra.program.model.mem;
using ghidra.program.model.pcode;
using ghidra.program.model.pcode;

public class BinaryExpression : OperandValue, ExpressionValue {
	public static readonly int INVALID_OP = -1;
	public static readonly int ADD = 0;
	public static readonly int SUB = 1;
	public static readonly int MUL = 2;
	public static readonly int DIV = 3;
	public static readonly int EQ = 4;
	public static readonly int AND = 5;

	private int spaceID;	// SpaceID of address space into which this expression returns a pointer
	private int wordSize;
//	private long wordMask;
	private AddressSpace constantSpace;
	
	private int opType;
	private ExpressionTerm left, right;

	public BinaryExpression(int op, ExpressionTerm l, ExpressionTerm r, AddressSpace c)
    {
		opType = op;
		left = l;
		right = r;
		wordSize = c.getSize()/8;
//		wordMask = c.getMaxOffset();
		spaceID = c.getSpaceID();
		constantSpace = c;
		switch (opType) {
			case ADD:
			case SUB:
			case MUL:
			case DIV:
			//case EQ: return r;
			case AND:
				break;
			default: throw new SledException("Unrecognized opType (" + opType + ") in Binary Expression");
		}
	}

	public void setSpace(AddressSpace space) {
		spaceID = space.getSpaceID();
		wordSize = space.getSize()/8;
//		wordMask = space.getMaxOffset();
	}

	/* @Override */
	public int length(MemBuffer buf,int off)
    {
		int leftLen = left.length(buf,off);
		int rightLen = right.length(buf, off);
		
		return (leftLen > rightLen ? leftLen : rightLen);
	}

	/* @Override */
	public ConstructorInfo getInfo(MemBuffer buf, int off)
    {
		return new ConstructorInfo(length(buf,off),0);
	}	

	/* @Override */
	public long longValue(MemBuffer buf, int off)
    {

		long l = left.longValue(buf, off);
		long r = right.longValue(buf, off);

		switch (opType) {
			case ADD: return l + r;
			case SUB: return l - r;
			case MUL: return l * r;
			case DIV: return l / r;
			//case EQ: return r;
			case AND: return l & r;
			default:					// Should never get executed
				return 0;
		}
	}

	/* @Override */
	public string toString(MemBuffer buf, int off)
    {
		long val = longValue(buf, off);
		if (val >= 0) {
			return "0x" + Long.toString(val,16);
		}
        return "-0x" + Long.toString(-val,16);
	}

	/**
	 * Method linkRelativeOffsets.
	 * @param opHash
	 */
	public void linkRelativeOffsets(Dictionary<string, Operand> opHash) {
		left.linkRelativeOffsets(opHash);
		right.linkRelativeOffsets(opHash);
	}

	/* @Override */
	public Handle getHandle(Position position, int off)
    {
		long val = /* wordMask & */ longValue(position.buffer(),off);
		Address a = constantSpace.getAddress(val);
		Varnode v = new Varnode(a,wordSize);
		return new Handle(v,spaceID,wordSize);
	}

	/* @Override */
	public Handle getHandle(List<PcodeOp> pcode, Position position, int off)
    {
		return getHandle(position,off); // a binary expression never has any associated pcode
	}

	/* @Override */
	public void getAllHandles(List<Handle> handles,Position position,int off)
    {
		handles.add(getHandle(position,off));
	}
	
	/* (non-Javadoc)
	 * @see ghidra.app.plugin.processors.generic.OperandValue#toList(java.util.ArrayList, ghidra.program.model.mem.MemBuffer, int)
	 */
	/* @Override */
	public void toList(List<Handle> list, Position position, int off)
    {
		list.add(getHandle(position, off));
	}

	/* (non-Javadoc)
	 * @see ghidra.app.plugin.processors.generic.OperandValue#getSize()
	 */
	/* @Override */
	public int getSize() {
		return wordSize * 8;
	}
}
